mkdir -p src/features/users/utils && cat > src/features/users/utils/filter-users.ts <<'EOF'
import { ROLES } from '@/lib/authorization';
import { User } from '@/types/api';

import { UsersFilterInput } from '../api/get-users';

export const filterUsers = (
  users: User[],
  { search, role }: UsersFilterInput,
) => {
  const query = search.trim().toLowerCase();

  return users.filter((user) => {
    if (role !== 'ALL' && ROLES[user.role] !== role) {
      return false;
    }

    if (!query) {
      return true;
    }

    const fullName = `${user.firstName} ${user.lastName}`.toLowerCase();

    return (
      fullName.includes(query) || user.email.toLowerCase().includes(query)
    );
  });
};
EOF
cat > src/features/users/utils/export-users-csv.ts <<'EOF'
import { User } from '@/types/api';
import { formatDate } from '@/utils/format';

const CSV_HEADERS = ['Name', 'Email', 'Role', 'Joined'];

const escapeCsvCell = (value: string) => {
  // Prefix cells that spreadsheet apps could read as formulas.
  const neutralised = /^[=+\-@\t\r]/.test(value) ? `'${value}` : value;

  return `"${neutralised.replace(/"/g, '""')}"`;
};

export const buildUsersCsv = (users: User[]) => {
  const rows = users.map((user) =>
    [
      `${user.firstName} ${user.lastName}`,
      user.email,
      user.role,
      formatDate(user.createdAt),
    ]
      .map(escapeCsvCell)
      .join(','),
  );

  // The byte order mark lets spreadsheet apps detect UTF-8 for accented names.
  return `﻿${[CSV_HEADERS.map(escapeCsvCell).join(','), ...rows].join('\r\n')}`;
};

export const downloadUsersCsv = (
  users: User[],
  fileName = 'users.csv',
) => {
  const blob = new Blob([buildUsersCsv(users)], {
    type: 'text/csv;charset=utf-8',
  });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');

  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 0);
};
EOF
